INSERT INTO public.saints (id, name, title, feast_day, feast_month, feast_day_num, born, died, patron_of, bio, full_bio, works, quotes, category, image, prayer, virtues, bible_refs, catechism_refs, church_doc_refs) VALUES
($$basilio-gregorio$$, $$São Basílio Magno e São Gregório Nazianzeno$$, $$Doutores da Igreja$$, $$2 de Janeiro$$, 1, 2, $$329/330, Capadócia$$, $$379/390, Capadócia$$, '{"Monges","Educadores"}'::text[], $$Dois dos três Padres Capadócios, defensores da doutrina trinitária contra o arianismo. Basílio fundou o monaquismo oriental.$$, $$Dois dos três Padres Capadócios, defensores da doutrina trinitária contra o arianismo. Basílio fundou o monaquismo oriental.$$, $$[]$$::jsonb, '{"\"A Bíblia é a carta de Deus para a humanidade.\""}'::text[], $$doctor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Sv_Vasilii_Velikii_%28765%29.jpg/440px-Sv_Vasilii_Velikii_%28765%29.jpg$$, NULL, '{"Sabedoria","Caridade"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$nome-jesus$$, $$Santíssimo Nome de Jesus$$, $$Nome acima de todo nome$$, $$3 de Janeiro$$, 1, 3, NULL, NULL, '{"Cristãos"}'::text[], $$Festa que celebra o santo Nome de Jesus, dado pelo anjo Gabriel antes da sua concepção, e que significa "Deus salva".$$, $$Festa que celebra o santo Nome de Jesus, dado pelo anjo Gabriel antes da sua concepção, e que significa "Deus salva".$$, $$[]$$::jsonb, '{"\"Ao nome de Jesus se dobre todo joelho.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/c/ce/Bernardino_siena.jpg/440px-Bernardino_siena.jpg$$, NULL, '{"Devoção"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$isabel-seton$$, $$Santa Isabel Ana Seton$$, $$Primeira Santa Americana$$, $$4 de Janeiro$$, 1, 4, $$1774, Nova York$$, $$1821, Emmitsburg, Maryland$$, '{"Viúvas","Escolas católicas"}'::text[], $$Convertida ao catolicismo, fundou as Irmãs da Caridade e o sistema de escolas paroquiais nos Estados Unidos.$$, $$Convertida ao catolicismo, fundou as Irmãs da Caridade e o sistema de escolas paroquiais nos Estados Unidos.$$, $$[]$$::jsonb, '{"\"Vivam simplesmente para que outros possam simplesmente viver.\""}'::text[], $$founder$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Elizabeth_Ann_Seton.jpg/440px-Elizabeth_Ann_Seton.jpg$$, NULL, '{"Caridade","Fé"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$joao-neumann$$, $$São João Neumann$$, $$Bispo de Filadélfia$$, $$5 de Janeiro$$, 1, 5, $$1811, Boêmia$$, $$1860, Filadélfia$$, '{"Educação católica"}'::text[], $$Bispo redentorista que construiu dezenas de escolas e igrejas na Filadélfia.$$, $$Bispo redentorista que construiu dezenas de escolas e igrejas na Filadélfia.$$, $$[]$$::jsonb, '{"\"Todo momento é um momento de graça.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/a/a3/St._John_Neumann.jpg/440px-St._John_Neumann.jpg$$, NULL, '{"Zelo","Humildade"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$epifania$$, $$Epifania do Senhor$$, $$Manifestação aos Gentios$$, $$6 de Janeiro$$, 1, 6, NULL, NULL, '{"Missionários"}'::text[], $$Solenidade que celebra a visita dos Reis Magos ao Menino Jesus, representando a revelação de Cristo a todos os povos.$$, $$Solenidade que celebra a visita dos Reis Magos ao Menino Jesus, representando a revelação de Cristo a todos os povos.$$, $$[]$$::jsonb, '{"\"Viemos do Oriente para adorar o Rei.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/Adorazione_dei_Magi_-_Gentile_da_Fabriano.jpg/440px-Adorazione_dei_Magi_-_Gentile_da_Fabriano.jpg$$, NULL, '{"Fé","Busca"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb)
