INSERT INTO public.saints (id, name, title, feast_day, feast_month, feast_day_num, born, died, patron_of, bio, full_bio, works, quotes, category, image, prayer, virtues, bible_refs, catechism_refs, church_doc_refs) VALUES
($$raimundo-penafort$$, $$São Raimundo de Peñafort$$, $$Padroeiro dos Canonistas$$, $$7 de Janeiro$$, 1, 7, $$1175, Barcelona$$, $$1275, Barcelona$$, '{"Advogados","Canonistas"}'::text[], $$Dominicano e grande jurista, compilou as Decretais de Gregório IX, sistematizando o Direito Canônico.$$, $$Dominicano e grande jurista, compilou as Decretais de Gregório IX, sistematizando o Direito Canônico.$$, $$[]$$::jsonb, '{"\"A justiça sem misericórdia é crueldade.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/f/f2/Ramon_de_Penyafort.jpg/440px-Ramon_de_Penyafort.jpg$$, NULL, '{"Justiça","Sabedoria"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$batismo-senhor$$, $$Batismo do Senhor$$, $$Início da Vida Pública$$, $$13 de Janeiro$$, 1, 13, NULL, NULL, '{"Catecúmenos"}'::text[], $$Festa que celebra o batismo de Jesus no rio Jordão por João Batista, quando o Espírito Santo desceu como pomba.$$, $$Festa que celebra o batismo de Jesus no rio Jordão por João Batista, quando o Espírito Santo desceu como pomba.$$, $$[]$$::jsonb, '{"\"Tu és o meu Filho amado, em Ti me comprazo.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/5/58/Baptism-of-Christ-Pietro-Perugino.jpg/440px-Baptism-of-Christ-Pietro-Perugino.jpg$$, NULL, '{"Humildade"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$antonio-abade$$, $$Santo Antão do Deserto$$, $$Pai do Monaquismo$$, $$17 de Janeiro$$, 1, 17, $$251, Egito$$, $$356, Egito$$, '{"Eremitas","Animais"}'::text[], $$Pai do monaquismo cristão, viveu mais de 80 anos como eremita no deserto egípcio, combatendo as tentações do demônio.$$, $$Pai do monaquismo cristão, viveu mais de 80 anos como eremita no deserto egípcio, combatendo as tentações do demônio.$$, $$[]$$::jsonb, '{"\"Vi todas as armadilhas do inimigo espalhadas pelo mundo e gemi: quem poderá escapar delas? Ouvi uma voz que me disse: A humildade.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Zurbaran_-_St._Anthony_the_Abbot.jpg/440px-Zurbaran_-_St._Anthony_the_Abbot.jpg$$, NULL, '{"Ascese","Oração"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sebastiao$$, $$São Sebastião$$, $$Mártir da Guarda Pretoriana$$, $$20 de Janeiro$$, 1, 20, $$256, Narbona$$, $$288, Roma$$, '{"Soldados","Atletas","Rio de Janeiro"}'::text[], $$Oficial romano que professava a fé cristã em segredo. Descoberto, foi condenado a ser flechado, sobreviveu e voltou a denunciar o imperador.$$, $$Oficial romano que professava a fé cristã em segredo. Descoberto, foi condenado a ser flechado, sobreviveu e voltou a denunciar o imperador.$$, $$[]$$::jsonb, '{"\"A fé em Cristo é mais forte que qualquer flecha.\""}'::text[], $$martyr$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Andrea_Mantegna_089.jpg/440px-Andrea_Mantegna_089.jpg$$, NULL, '{"Coragem","Fé"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$agnes$$, $$Santa Inês$$, $$Virgem e Mártir$$, $$21 de Janeiro$$, 1, 21, $$291, Roma$$, $$304, Roma$$, '{"Jovens","Noivas","Pureza"}'::text[], $$Jovem romana que consagrou sua virgindade a Cristo e foi martirizada aos 12 anos durante a perseguição de Diocleciano.$$, $$Jovem romana que consagrou sua virgindade a Cristo e foi martirizada aos 12 anos durante a perseguição de Diocleciano.$$, $$[]$$::jsonb, '{"\"Já estou unida Àquele a quem os anjos servem.\""}'::text[], $$virgin$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/Jos%C3%A9_de_Ribera_064.jpg/440px-Jos%C3%A9_de_Ribera_064.jpg$$, NULL, '{"Pureza","Coragem"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb)
