INSERT INTO public.saints (id, name, title, feast_day, feast_month, feast_day_num, born, died, patron_of, bio, full_bio, works, quotes, category, image, prayer, virtues, bible_refs, catechism_refs, church_doc_refs) VALUES
($$conversao-paulo$$, $$Conversão de São Paulo$$, $$Apóstolo dos Gentios$$, $$25 de Janeiro$$, 1, 25, $$5 d.C., Tarso$$, $$64/67, Roma$$, '{"Missionários","Teólogos"}'::text[], $$A conversão de Saulo de Tarso no caminho de Damasco é um dos eventos mais importantes do cristianismo.$$, $$A conversão de Saulo de Tarso no caminho de Damasco é um dos eventos mais importantes do cristianismo.$$, $$[]$$::jsonb, '{"\"Já não sou eu quem vive, é Cristo que vive em mim.\""}'::text[], $$apostle$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Caravaggio_-_La_conversione_di_San_Paolo.jpg/440px-Caravaggio_-_La_conversione_di_San_Paolo.jpg$$, NULL, '{"Conversão","Zelo"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$brígida-irlanda$$, $$Santa Brígida da Irlanda$$, $$A Maria dos Gaélicos$$, $$1 de Fevereiro$$, 2, 1, $$451, Irlanda$$, $$525, Kildare$$, '{"Irlanda","Poetas"}'::text[], $$Uma das padroeiras da Irlanda, fundou o mosteiro de Kildare, centro de arte e cultura cristã.$$, $$Uma das padroeiras da Irlanda, fundou o mosteiro de Kildare, centro de arte e cultura cristã.$$, $$[]$$::jsonb, '{"\"Cristo é visto em cada estranho.\""}'::text[], $$virgin$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/St_Brigid%27s_Cross.jpg/440px-St_Brigid%27s_Cross.jpg$$, NULL, '{"Generosidade","Hospitalidade"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$apresentacao-senhor$$, $$Apresentação do Senhor$$, $$Candelária$$, $$2 de Fevereiro$$, 2, 2, NULL, NULL, '{"Vida consagrada"}'::text[], $$Festa que celebra a apresentação de Jesus no Templo por Maria e José, quando Simeão o reconheceu como "luz para iluminar as nações".$$, $$Festa que celebra a apresentação de Jesus no Templo por Maria e José, quando Simeão o reconheceu como "luz para iluminar as nações".$$, $$[]$$::jsonb, '{"\"Os meus olhos viram a tua salvação.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Andrea_Mantegna_049.jpg/440px-Andrea_Mantegna_049.jpg$$, NULL, '{"Obediência","Esperança"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$bras$$, $$São Brás$$, $$Bispo e Mártir$$, $$3 de Fevereiro$$, 2, 3, $$Séc. III, Armênia$$, $$316, Sebaste$$, '{"Doenças de garganta"}'::text[], $$Bispo e médico armênio, é invocado contra doenças da garganta. Salvou um menino engasgado com uma espinha de peixe.$$, $$Bispo e médico armênio, é invocado contra doenças da garganta. Salvou um menino engasgado com uma espinha de peixe.$$, $$[]$$::jsonb, '{"\"A cura do corpo começa pela cura da alma.\""}'::text[], $$martyr$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Hans_Memling_-_St_Blaise_-_WGA15003.jpg/440px-Hans_Memling_-_St_Blaise_-_WGA15003.jpg$$, NULL, '{"Cura","Compaixão"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$agata$$, $$Santa Ágata$$, $$Virgem e Mártir$$, $$5 de Fevereiro$$, 2, 5, $$Séc. III, Catânia$$, $$251, Catânia$$, '{"Bombeiros","Joalheiros","Catânia"}'::text[], $$Jovem siciliana que resistiu aos avanços do prefeito Quintiano e foi horrivelmente torturada por sua fé.$$, $$Jovem siciliana que resistiu aos avanços do prefeito Quintiano e foi horrivelmente torturada por sua fé.$$, $$[]$$::jsonb, '{"\"Senhor, que me criastes e me protegestes desde a infância.\""}'::text[], $$virgin$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/d/d5/Francisco_de_Zurbar%C3%A1n_-_Saint_Agatha_-_Google_Art_Project.jpg/440px-Francisco_de_Zurbar%C3%A1n_-_Saint_Agatha_-_Google_Art_Project.jpg$$, NULL, '{"Castidade","Fortaleza"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb)
