INSERT INTO public.saints (id, name, title, feast_day, feast_month, feast_day_num, born, died, patron_of, bio, full_bio, works, quotes, category, image, prayer, virtues, bible_refs, catechism_refs, church_doc_refs) VALUES
($$paulo-miki$$, $$São Paulo Miki e Companheiros$$, $$Mártires do Japão$$, $$6 de Fevereiro$$, 2, 6, $$1562, Japão$$, $$1597, Nagasáqui$$, '{"Japão"}'::text[], $$Jesuíta japonês, crucificado em Nagasáqui com outros 25 mártires, os primeiros mártires do Japão.$$, $$Jesuíta japonês, crucificado em Nagasáqui com outros 25 mártires, os primeiros mártires do Japão.$$, $$[]$$::jsonb, '{"\"Agradeço a Deus por morrer neste dia.\""}'::text[], $$martyr$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/1/1d/Martyrs_of_Japan.jpg/440px-Martyrs_of_Japan.jpg$$, NULL, '{"Martírio","Fé"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$escolastica$$, $$Santa Escolástica$$, $$Irmã de São Bento$$, $$10 de Fevereiro$$, 2, 10, $$480, Núrsia$$, $$547, Monte Cassino$$, '{"Monjas","Tempestades"}'::text[], $$Irmã gêmea de São Bento, fundadora do ramo feminino dos beneditinos. Sua oração provocou uma tempestade para reter o irmão.$$, $$Irmã gêmea de São Bento, fundadora do ramo feminino dos beneditinos. Sua oração provocou uma tempestade para reter o irmão.$$, $$[]$$::jsonb, '{"\"O amor é mais forte que qualquer regra.\""}'::text[], $$virgin$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/6/62/Ary_Scheffer_-_Saints_Augustine_and_Monica_%281846%29.jpg/440px-Ary_Scheffer_-_Saints_Augustine_and_Monica_%281846%29.jpg$$, NULL, '{"Oração","Amor fraterno"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$nossa-senhora-lourdes$$, $$Nossa Senhora de Lourdes$$, $$A Imaculada Conceição$$, $$11 de Fevereiro$$, 2, 11, NULL, NULL, '{"Enfermos"}'::text[], $$Em 1858, a Virgem Maria apareceu 18 vezes a Santa Bernadette na gruta de Massabielle, em Lourdes, França.$$, $$Em 1858, a Virgem Maria apareceu 18 vezes a Santa Bernadette na gruta de Massabielle, em Lourdes, França.$$, $$[]$$::jsonb, '{"\"Eu sou a Imaculada Conceição.\""}'::text[], $$virgin$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Lourdes_-_Pair_of_statues.jpg/440px-Lourdes_-_Pair_of_statues.jpg$$, NULL, '{"Pureza","Cura"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$cirilo-metodio$$, $$Santos Cirilo e Metódio$$, $$Apóstolos dos Eslavos$$, $$14 de Fevereiro$$, 2, 14, $$826/827, Tessalônica$$, $$869/885$$, '{"Europa","Eslavos"}'::text[], $$Irmãos gregos que evangelizaram os povos eslavos. Cirilo criou o alfabeto glagolítico, base do cirílico.$$, $$Irmãos gregos que evangelizaram os povos eslavos. Cirilo criou o alfabeto glagolítico, base do cirílico.$$, $$[]$$::jsonb, '{"\"A Palavra de Deus deve ser ouvida na língua de cada povo.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/6/63/Slavonic_wenceslas_bible.jpg/440px-Slavonic_wenceslas_bible.jpg$$, NULL, '{"Evangelização","Cultura"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$catedra-pedro$$, $$Cátedra de São Pedro$$, $$Pedra da Igreja$$, $$22 de Fevereiro$$, 2, 22, NULL, NULL, '{"Papado"}'::text[], $$Festa que celebra a autoridade de ensino que Cristo confiou a Pedro e seus sucessores como chefe da Igreja.$$, $$Festa que celebra a autoridade de ensino que Cristo confiou a Pedro e seus sucessores como chefe da Igreja.$$, $$[]$$::jsonb, '{"\"Tu és Pedro e sobre esta pedra edificarei a minha Igreja.\""}'::text[], $$apostle$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/2/2d/Cathedra_Petri_adjusted.JPG/440px-Cathedra_Petri_adjusted.JPG$$, NULL, '{"Autoridade","Fé"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb)
